import React from 'react';
import { Link } from 'react-router-dom';
import wordCloudImage from './test1.jpg';

const WordCloud = () => {
  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        minHeight: '100vh',
        padding: '2rem',
        background: 'linear-gradient(135deg, #FF9A9E 0%, #FAD0C4 100%)',
        textAlign: 'center',
        fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
        color: '#333',
      }}
    >
      <h2 style={{ fontSize: '2.5rem', marginBottom: '1.5rem' }}>WordCloud</h2>
      <img
        src={wordCloudImage}
        alt="wordcloud"
        style={{ width: '15em', height: 'auto', borderRadius: '15px', boxShadow: '0 4px 15px rgba(255, 154, 158, 0.5)' }}
      />
      <Link to="/" style={{ marginTop: '2rem', textDecoration: 'none' }}>
        <button
          style={{
            padding: '0.75rem 1.5rem',
            fontSize: '1.1rem',
            borderRadius: '30px',
            border: 'none',
            background: 'linear-gradient(135deg, #FF6B6B 0%, #FFD93D 100%)',
            color: '#1a1a1a',
            cursor: 'pointer',
            boxShadow: '0 4px 15px rgba(255, 217, 61, 0.5)',
            transition: 'all 0.3s ease',
            minWidth: '120px',
          }}
          onMouseEnter={e => {
            e.target.style.background = 'linear-gradient(135deg, #FFD93D 0%, #FF6B6B 100%)';
            e.target.style.color = '#fff';
            e.target.style.boxShadow = '0 6px 20px rgba(255, 107, 107, 0.75)';
          }}
          onMouseLeave={e => {
            e.target.style.background = 'linear-gradient(135deg, #FF6B6B 0%, #FFD93D 100%)';
            e.target.style.color = '#1a1a1a';
            e.target.style.boxShadow = '0 4px 15px rgba(255, 217, 61, 0.5)';
          }}
        >
          Back
        </button>
      </Link>
    </div>
  );
};

export default WordCloud;
